// POST /api/ai/runs (D-022, D-025): start an AI build/rebuild for one of the caller's books.
// Body: { bookId: uuid, trigger?: 'build' | 'rebuild' } (default 'build'). The body
// trigger is only a hint (T16 #3): once the book has a finished live AI run or
// its doc was generated by AI (meta.generator 'ai'), the run is a 'rebuild' —
// so the per-book rebuild cap can't be dodged by sending 'build'.
// Rate guard (T16 #19): rule runs (AI off) run synchronously and are free, so at
// most one per book per 10 s — a newer request gets 429 limit 'rate'.
// Responses (all no-store):
//   201 { runId, mode, state }                     — mode 'rule' runs synchronously (state done|failed)
//   400 { error: 'invalid_body' } | 401 | 403 | 404 { error: 'not_found' }
//   409 { error: 'already_running', runId | null } | 409 { error: 'user_edited' }
//   429 { error: 'limit', limit: 'daily_builds' | 'rebuilds' | 'analysed_photos' | 'rate' | 'budget_exhausted' }
//       ('rate' also sets Retry-After in seconds; 'budget_exhausted' = D-059 global daily AI budget
//       used up — live mode only, no run created, nothing counted, the rule album stays)
//   422 { error: 'unsupported_design' } — books.design_style has no layouts yet (M10b A19 review S1;
//       geometric / scrapbook rows only exist when inserted directly — the New book form refuses them)
//   500 { error: 'server_error' }
// Logs carry error codes only — never ids, run data or photo data.
import { type NextRequest } from "next/server";
import { z } from "zod";
import { startRun } from "@/lib/ai/orchestrator";
import { getCurrentUser } from "@/lib/auth/current-user";
import { isSameOrigin } from "@/lib/auth/same-origin";
import { docOrigin } from "@/lib/book/replaceable";
import { getActiveRunForBook, getLatestRunForBook, hasFinishedLiveAiRun } from "@/lib/db/agent-runs";
import { getMyBook } from "@/lib/db/books";
import { errorCodeOf, json, unavailableIfTimeout } from "@/lib/http/json";
import { isUuid } from "@/lib/uuid";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
// Rule mode (AI off) curates + lays out synchronously inside this request.
export const maxDuration = 60;

const MAX_BODY_BYTES = 1024;
/** T16 #19: minimum gap after a rule-mode run of the same book. */
const RULE_RUN_MIN_INTERVAL_MS = 10_000;

const BodySchema = z.object({
  bookId: z.string().max(64),
  trigger: z.enum(["build", "rebuild"]).default("build"),
});

export async function POST(request: NextRequest) {
  if (!isSameOrigin(request)) return json({ error: "forbidden" }, 403);

  try {
    const user = await getCurrentUser();
    if (!user) return json({ error: "unauthenticated" }, 401);

    const text = await request.text();
    if (text.length > MAX_BODY_BYTES) return json({ error: "invalid_body" }, 400);
    let raw: unknown;
    try {
      raw = JSON.parse(text);
    } catch {
      return json({ error: "invalid_body" }, 400);
    }
    const parsed = BodySchema.safeParse(raw);
    if (!parsed.success) return json({ error: "invalid_body" }, 400);
    const { bookId, trigger: hintedTrigger } = parsed.data;

    if (!isUuid(bookId)) return json({ error: "not_found" }, 404);
    const book = await getMyBook(bookId);
    if (!book) return json({ error: "not_found" }, 404);

    const latest = await getLatestRunForBook(book.id);
    if (latest && latest.mode === "rule") {
      const age = Date.now() - Date.parse(latest.started_at);
      if (Number.isFinite(age) && age < RULE_RUN_MIN_INTERVAL_MS) {
        const retryAfter = Math.max(1, Math.ceil((RULE_RUN_MIN_INTERVAL_MS - Math.max(0, age)) / 1000));
        return json({ error: "limit", limit: "rate" }, 429, { "retry-after": String(retryAfter) });
      }
    }

    const isRebuild =
      docOrigin(book.doc).generator === "ai" || (await hasFinishedLiveAiRun(book.id));
    const trigger = isRebuild ? "rebuild" : hintedTrigger;

    const result = await startRun({ bookId: book.id, userId: user.id, trigger });
    if (result.ok) {
      return json({ runId: result.runId, mode: result.mode, state: result.state }, 201);
    }
    switch (result.error) {
      case "already_running": {
        const active = await getActiveRunForBook(book.id);
        return json({ error: "already_running", runId: active?.id ?? null }, 409);
      }
      case "user_edited":
        return json({ error: "user_edited" }, 409);
      case "limit":
        return json({ error: "limit", limit: result.limit ?? "daily_builds" }, 429);
      case "unsupported_design":
        return json({ error: "unsupported_design" }, 422);
      case "not_found":
      default:
        return json({ error: "not_found" }, 404);
    }
  } catch (err) {
    const unavailable = unavailableIfTimeout(err, { route: "ai-runs" });
    if (unavailable) return unavailable;
    console.error(`[ai-runs] start failed (${errorCodeOf(err)})`);
    return json({ error: "server_error" }, 500);
  }
}
